500	            &mut hkey,
501	        );
502	
503	        if result == ERROR_FILE_NOT_FOUND {
504	            return Err(anyhow!("registry key not found: HKLM\\{}", subkey));
505	        }
506	        if result != WIN32_ERROR(0) {
507	            return Err(anyhow!("RegOpenKeyExW failed: {}", result.0));
508	        }
509	
510	        let name_wide: Vec<u16> = name.encode_utf16().chain(std::iter::once(0)).collect();
511	
512	        // Query the required buffer size.
513	        let mut data_size = 0u32;
514	        let mut value_type = REG_VALUE_TYPE::default();
515	        let size_result = RegQueryValueExW(
