/// Returns the [`SyncPath`] whose `path` prefix matches `path`, or `None`.
fn detect_sync_provider<'a>(&'a self, path: &str) -> Option<&'a SyncPath> {
    let lower = path.to_lowercase();
    for sp in &self.sync_paths {
        if lower.starts_with(&sp.path.to_lowercase()) {
            return Some(sp);
        }
    }
    None
}

